def is_power_of_5(x):
    if x <= 0:
        return False
    if x == 1:
        return True
    while x % 5 == 0:
        x //= 5
    return x == 1

solutions = []
for n in range(3, 2001):
    v = 2**n - 3
    if is_power_of_5(v):
        k = 0
        temp_v = v
        while temp_v > 1:
            temp_v //= 5
            k += 1
        solutions.append((n, k))

print(solutions)

